// Offline Window scheduler fixture; link tests/offline_broker_guard.cpp, never production transport.
#define main booking_application_main
#include "../src/main.cpp"
#undef main
#include <QTextStream>
#include <cstdio>
class UiProbe {public:static QJsonObject run(QString root,int selected,QString mode){int initial=qEnvironmentVariableIntValue("PROBE_READY_COUNT");if(initial<=0)initial=selected;initial=qMin(initial,selected);
 Window w(root,false);auto detach=[&]{for(int k=0;k<w.queryConnectionCount_;++k)if(w.queryWorkers_[k])QObject::disconnect(&w,&Window::work,w.queryWorkers_[k],&Worker::execute);};detach();auto spin=[&](int ms=40){QElapsedTimer t;t.start();while(t.elapsed()<ms)QApplication::processEvents(QEventLoop::AllEvents,10);};spin();w.connectionThreads_->setValue(selected);detach();spin();
 w.autoLoad_->setChecked(false);w.debounce_.stop();w.hospital_=w.jobHospital_="H_FIXTURE";{QSignalBlocker b(w.department_);w.department_->clear();w.department_->addItem("choose");w.department_->addItem("fixture department","D1");w.department_->setItemData(1,"F1",Qt::UserRole+1);w.department_->setCurrentIndex(1);}
 QList<QDate>dates;for(int i=0;i<7;++i)dates.append(QDate(2026,11,12).addDays(i));w.calendar_->setDisplayedMonth(dates[0]);w.calendar_->setSelectedDates(dates);for(int k=0;k<w.queryConnectionCount_;++k){auto&q=w.querySlots_[k];q.ready=k<initial;q.warming=q.failed=q.resetting=false;q.api=0;q.http=4;q.uses=0;q.hospital=w.hospital_;q.observed.start();q.cancel->store(false);}w.activeQuerySlot_=0;w.cancel_->store(false);w.mirrorActiveQuerySlot();w.updateControls();
 QJsonArray events,checks;int failures=0;auto check=[&](QString n,bool ok){checks.append(QJsonObject{{"name",n},{"pass",ok}});if(!ok)++failures;};QVector<int>inflight(16,0),api(16,0),http(16,4);int parallel=0,maxParallel=0,details=0,plans=0,warm=0,warmInflight=0,maxWarm=0,firstDetailAt=-1,firstWarmDone=-1,detailsBeforeAllWarm=0;bool perSlot=true;QJsonObject rendered;QEventLoop done;QElapsedTimer elapsed;bool timeout=false;
 auto tag=[](QJsonObject&r,QJsonObject p){for(auto k:{"_connection_slot","_connection_epoch","_request_id","_background","_batch_id","_date_key"})if(p.contains(k))r[k]=p.value(k);};
 auto summary=[&](QString date){return QJsonObject{{"date",date},{"doctor_name",""},{"period",""},{"remaining",QJsonValue(QJsonValue::Null)},{"status",QString::fromUtf8("无号")},{"row_kind","department_calendar"},{"raw_status",4}};};
 QObject::connect(&w,&Window::work,&w,[&](QString op,QJsonObject p){int slot=p.value("_connection_slot").toInt();events.append(QJsonObject{{"op",op},{"slot",slot},{"date",p.value("date")},{"at_ms",int(elapsed.elapsed())},{"params",p}});
 if(op=="availability_plan"){++plans;QTimer::singleShot(30,&w,[&,p,slot]{QJsonArray rows,cal,required;for(int i=0;i<dates.size();++i){QString date=dates[i].toString("yyyyMMdd");auto row=summary(date);bool needs=mode=="detail"||mode=="fastdetail"||(mode=="mixed"&&(i%2==1));if(needs){row["status"]=QString::fromUtf8("有号");row["raw_status"]=1;required.append(date);}else rows.append(row);cal.append(row);}api[slot]+=2;http[slot]+=2;QJsonObject r{{"status","complete"},{"business_success",true},{"hospital_code","H_FIXTURE"},{"hospital_system","new"},{"rows",rows},{"detail_dates",required},{"calendar_rows",cal},{"session_kept_open",true},{"query_allowed",true},{"performance",QJsonObject{{"session_api_used",api[slot]},{"http_dispatches",2}}},{"runtime",QJsonObject{{"http_dispatches",http[slot]}}}};tag(r,p);w.completed("availability_plan",r);});
 }else if(op=="availability"){if(firstDetailAt<0)firstDetailAt=int(elapsed.elapsed());if(warmInflight>0)++detailsBeforeAllWarm;++details;++inflight[slot];perSlot&=inflight[slot]==1;++parallel;maxParallel=qMax(maxParallel,parallel);QString date=p.value("date").toString();int index=dates.indexOf(QDate::fromString(date,"yyyyMMdd"));const int delay=mode=="fastdetail"?10:80+(6-index)*5;QTimer::singleShot(delay,&w,[&,p,slot,date,index]{--inflight[slot];--parallel;bool no=mode=="empty"||(mode=="mixed"&&index%2==0);auto row=no?summary(date):QJsonObject{{"date",date},{"doctor_name","fixture "+date},{"remaining",3},{"status",QString::fromUtf8("有号")},{"row_kind","doctor_period"}};api[slot]+=1;http[slot]+=1;QJsonObject r{{"status","complete"},{"business_success",true},{"hospital_code","H_FIXTURE"},{"rows",QJsonArray{row}},{"session_kept_open",true},{"query_allowed",true},{"performance",QJsonObject{{"session_api_used",api[slot]},{"http_dispatches",1}}},{"runtime",QJsonObject{{"http_dispatches",http[slot]}}}};tag(r,p);w.completed("availability",r);});
 }else if(op=="prewarm"){++warm;++warmInflight;maxWarm=qMax(maxWarm,warmInflight);QTimer::singleShot((mode=="fastdetail"?700:100)+(slot%3)*30,&w,[&,p,slot]{--warmInflight;if(firstWarmDone<0)firstWarmDone=int(elapsed.elapsed());api[slot]=0;http[slot]=4;QJsonObject r{{"status","ready"},{"business_success",true},{"session_kept_open",true},{"query_allowed",true},{"performance",QJsonObject{{"session_api_used",0}}},{"runtime",QJsonObject{{"http_dispatches",4}}}};tag(r,p);w.completed("prewarm",r);});}
 });QObject::connect(&w,&Window::resultRendered,&w,[&](QJsonObject r){if(r.value("status")==QJsonValue("complete")&&r.value("queried_date_count").toInt()==7){rendered=r;done.quit();}});QTimer watchdog;watchdog.setSingleShot(true);QObject::connect(&watchdog,&QTimer::timeout,&done,[&]{timeout=true;done.quit();});elapsed.start();watchdog.start(5000);w.query();done.exec();int duration=elapsed.elapsed();watchdog.stop();check("all_selected_dates_complete",!timeout&&w.rows_->rowCount()==7);check("each_slot_at_most_one_date_inflight",perSlot);check("maximum_bounded_by_configured_owners",maxParallel<=selected);check("seven_detail_dates_use_observed_parallel_capacity",plans==0||mode!="detail"||initial<selected||maxParallel==qMin(7,selected));check("two_ready_slots_serve7details_without_extra_prewarm",plans==0||mode!="detail"||selected<2||initial<selected||warm==0);check("one_slot_safely_rewarms_after_four_dates",plans==0||mode!="detail"||selected!=1||warm==1);check("all_no_inventory_plan_skips_details_and_warm",mode!="empty"||plans==0||(details==0&&warm==0));QStringList order;for(int i=0;i<w.rows_->rowCount();++i)order.append(w.rows_->item(i,0)->text());bool sorted=true;for(int i=1;i<order.size();++i)sorted&=order[i-1]<=order[i];check("out_of_order_results_render_in_selected_date_order",sorted);QJsonObject out{{"status",failures?"FAIL":"PASS"},{"checks",checks},{"failures",failures},{"mode",mode},{"configured_threads",selected},{"initial_ready",initial},{"max_warm_inflight",maxWarm},{"first_detail_at_ms",firstDetailAt},{"first_warm_done_ms",firstWarmDone},{"warm_inflight_when_result_rendered",warmInflight},{"detail_dispatches_while_other_warm_inflight",detailsBeforeAllWarm},{"elapsed_ms",duration},{"plans",plans},{"availability_dispatches",details},{"prewarms",warm},{"max_parallel_dates",maxParallel},{"rows",w.rows_->rowCount()},{"performance",rendered.value("performance")},{"events",events},{"fixture_plan_delay_ms",30},{"fixture_detail_delay_range_ms","80..110"},{"fixture_prewarm_delay_ms","100/130/160 by slot"},{"scope","Qt scheduling fixture with real QTimer waits; not website speed"},{"network_requests",0},{"real_order_submissions",0}};
 w.stop();spin();for(int k=0;k<w.queryConnectionCount_;++k)w.queryThreads_[k]->quit();for(int k=0;k<w.queryConnectionCount_;++k)w.queryThreads_[k]->wait(10000);return out;}};
int main(int argc,char**argv){QApplication app(argc,argv);const auto a=app.arguments();auto out=UiProbe::run(a.at(1),qEnvironmentVariableIntValue("PROBE_CONNECTIONS"),qEnvironmentVariable("PROBE_MODE","detail"));const auto raw=QJsonDocument(out).toJson(QJsonDocument::Indented);fwrite(raw.constData(),1,raw.size(),stdout);return out.value("status")==QJsonValue("PASS")?0:1;}
